  function runGeneration(pop, scored, rand, sigma) {
    const D = DEFAULTS, next = [];
    scored.sort((a, b) => b.fitness - a.fitness);
    for (let i = 0; i < D.elites; i++) next.push(JSON.parse(JSON.stringify(scored[i].net)));
